-- PT118-S4-Q15. Batch 03.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch03$PT118-S4-Q15$batch03$ AND q.stimulus=$batch03$The cost of a semester’s tuition at a certain university is based on the number of courses in which a student enrolls that semester. Although the cost per course at that university has not risen in four years, many of its students who could afford the tuition when they first enrolled now claim they can no longer afford it.$batch03$ AND q.prompt=$batch03$Each of the following, if true, helps to resolve the apparent discrepancy above EXCEPT:$batch03$ AND q.correct_choice=$batch03$A$batch03$) THEN RAISE EXCEPTION 'Question changed: PT118-S4-Q15'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch03$PT118-S4-Q15$batch03$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT118-S4-Q15'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch03$PT118-S4-Q15$batch03$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch03$Given that$batch03$, $batch03$The cost per course has not risen in four years, and these students could once afford tuition.$batch03$), (1, $batch03$How can it be that$batch03$, $batch03$Many of them now say they cannot afford it?$batch03$), (2, $batch03$Evaluate$batch03$, $batch03$Affordability depends on what students pay and what they have. They could be paying more through more courses, or have less money because of higher living costs, lost scholarships or lost jobs. Each working answer changes one side.$batch03$), (3, $batch03$Goal$batch03$, $batch03$Four choices raise what students owe or cut what they have. The answer will do neither.$batch03$)) v(position,label,body) WHERE q.qid=$batch03$PT118-S4-Q15$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch03$A$batch03$, $batch03$Faculty salaries rising does not change what students pay; tuition per course is flat. It does not explain why students can no longer afford it.$batch03$), ($batch03$B$batch03$, $batch03$Students must take more courses per semester, and tuition is charged per course, so their tuition rises.$batch03$), ($batch03$C$batch03$, $batch03$Higher living costs leave less money for tuition.$batch03$), ($batch03$D$batch03$, $batch03$Scholarships are renewed only for high grades. Students who lose them pay more.$batch03$), ($batch03$E$batch03$, $batch03$Part-time jobs once held by students went to nonstudents. Students lost income.$batch03$)) v(letter,body) WHERE q.qid=$batch03$PT118-S4-Q15$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
